const html = $input.first().json.data || '';
const cleaned = html
  .replace(/<script[\s\S]*?<\/script>/gi,' ')
  .replace(/<style[\s\S]*?<\/style>/gi,' ')
  .replace(/<!--[\s\S]*?-->/g,' ')
  .replace(/<[^>]+>/g,' ')
  .replace(/\s+/g,' ')
  .trim();

const text = cleaned.slice(0, 28000); // duro pero seguro (≈6-8k tokens)
const signals = {
  url: $json.url || '',
  page_title: $json.pageTitle || '',
  has_wa: /wa\.me|api\.whatsapp\.com/i.test(html),
  has_tel: /tel:/i.test(html),
  has_mailto: /mailto:/i.test(html),
  has_checkout: /checkout|carrito|add to cart|woocommerce/i.test(html),
  has_booking: /calendly|book now|appointment|reserva/i.test(html),
  social: [...new Set((html.match(/instagram\.com|linkedin\.com|facebook\.com|youtube\.com/gi) || []).map(s => s.toLowerCase()))]
};

return [{ url: signals.url, pageTitle: signals.page_title, text, signals }];

// Obtener el número de teléfono
let phoneNumber = $('Loop Over Items').first().json.TELEFONO; // o el campo que contenga el número

// Limpiar el número (quitar espacios, guiones, paréntesis, etc.)
let cleanNumber = phoneNumber.replace(/[^0-9]/g, '');

// Asegurarse de que tenga el código de país
// Si no empieza con código de país, añadir uno (ejemplo: 34 para España, 56 para Chile)
if (!cleanNumber.startsWith('34') && !cleanNumber.startsWith('56')) {
  cleanNumber = '34' + cleanNumber; // Ajusta según tu país
}

// Formatear al estilo Evolution API
let evolutionFormat = cleanNumber + '@s.whatsapp.net';

return [{
  json: {
    phone_number: phoneNumber,           // original
    clean_number: cleanNumber,           // limpio
    whatsapp_id: evolutionFormat         // formato Evolution API
  }
}];
